/**
 * Deterministic RNG for the Sanguo engine.
 *
 * The whole point of a referee engine is that the model cannot roll dice.
 * That guarantee is worthless if the dice are `Math.random()`: a test could
 * not pin an outcome, a replay could not reproduce a session, and a save could
 * not be audited. So the generator state lives INSIDE the save file and every
 * roll advances it in a fixed, serializable way.
 *
 * Algorithm: xorshift32. Chosen over an LCG because it needs no multiply (the
 * device runs `--jitless`, so we keep the hot path to shifts and xors) and
 * still has a period of 2^32-1 with good low-bit behaviour.
 *
 * The seed is part of the save. Loading a save resumes the exact sequence, so
 * "reload and reroll" is not a strategy.
 */

const MASK = 0xffffffff

/** Advance one xorshift32 step and return the new unsigned 32-bit state. */
export function nextState(state) {
  let x = state >>> 0
  if (x === 0) {
    // xorshift32 has a fixed point at zero; escape it so a corrupt save with
    // seed 0 still produces a usable stream instead of freezing every roll.
    x = 0x9e3779b9
  }
  x ^= x << 13
  x >>>= 0
  x ^= x >>> 17
  x ^= x << 5
  x >>>= 0
  return x
}

/**
 * One roll of an inclusive [1, sides] die.
 * @returns {{ value: number, state: number }}
 */
export function rollDie(state, sides) {
  const next = nextState(state)
  const value = (next % sides) + 1
  return { value, state: next }
}

/**
 * Roll `count` dice and sum them, advancing the stream once per die.
 * @returns {{ total: number, faces: number[], state: number }}
 */
export function rollDice(state, count, sides) {
  let cursor = state
  let total = 0
  const faces = []
  for (let index = 0; index < count; index += 1) {
    const rolled = rollDie(cursor, sides)
    cursor = rolled.state
    faces.push(rolled.value)
    total += rolled.value
  }
  return { total, faces, state: cursor }
}

/**
 * Deterministic 1..100 check roll. Kept separate from `rollDie` so callers
 * cannot accidentally pass a sides count that makes the distribution weird.
 */
export function rollCheck(state) {
  return rollDie(state, 100)
}

/**
 * Pick one element deterministically. Used for NPC mood jitter and for
 * choosing among equally-weighted world events.
 */
export function pickOne(state, items) {
  if (!Array.isArray(items) || items.length === 0) {
    return { value: undefined, state }
  }
  const rolled = rollDie(state, items.length)
  return { value: items[rolled.value - 1], state: rolled.state }
}

/** Derive a fresh seed from a string, so a named run is reproducible. */
export function seedFrom(text) {
  let hash = 0x811c9dc5
  const input = String(text)
  for (let index = 0; index < input.length; index += 1) {
    hash ^= input.charCodeAt(index)
    hash = Math.imul(hash, 0x01000193) >>> 0
  }
  return hash === 0 ? 0x9e3779b9 : hash
}
